INSERT INTO cultural_traditions (name, description, district, category, origin_story, significance, when_practiced, participants, materials_required, steps_or_process, cultural_values, modern_relevance, preservation_status, images) VALUES
('Kumaoni Folk Dance (Chholiya)', 'Traditional sword dance performed during weddings and festivals', 'Almora', 'dance', 'Originated from the martial traditions of Kumaon region, performed by warriors', 'Represents valor, protection, and celebration of life events', 'Weddings, festivals like Diwali and Holi', 'Men of all ages, traditionally performed by grooms party', '["swords", "traditional_dhoti", "turban", "drums"]', '["formation_in_circle", "rhythmic_sword_movements", "synchronized_steps", "call_and_response_singing"]', '["courage", "community_bonding", "celebration", "heritage_preservation"]', 'Still performed at weddings, cultural events, and tourism shows', 'active', '["chholiya1.jpg", "chholiya2.jpg"]'),
('Garhwali Langvir Nritya', 'Acrobatic folk dance where performers balance on bamboo poles', 'Tehri Garhwal', 'dance', 'Ancient tradition showcasing physical prowess and spiritual devotion', 'Demonstrates human potential and connection with divine through physical mastery', 'Religious festivals, especially during Navratri', 'Young men trained in acrobatics', '["bamboo_poles", "traditional_costume", "dhol", "damau"]', '["pole_setup", "climbing_technique", "balancing_acts", "aerial_movements", "group_coordination"]', '["discipline", "devotion", "physical_fitness", "fearlessness"]', 'Performed at cultural festivals and attracts tourists', 'active', '["langvir1.jpg", "langvir2.jpg"]'),
('Jagar (Spirit Calling Ritual)', 'Traditional ritual to invoke local deities and spirits', 'Kumaon and Garhwal', 'ritual', 'Ancient shamanic practice connecting communities with local deities', 'Healing, problem-solving, and maintaining spiritual balance in community', 'During illness, community problems, or festivals', 'Jagari (medium), musicians, community members', '["dhol", "damau", "thali", "rice", "flowers", "incense"]', '["preparation_of_sacred_space", "invocation_chants", "rhythmic_drumming", "spirit_possession", "divine_guidance"]', '["spiritual_healing", "community_support", "ancestral_wisdom", "problem_resolution"]', 'Still practiced in villages for healing and guidance', 'active', '["jagar1.jpg", "jagar2.jpg"]'),
('Basant Panchami Celebration', 'Spring festival celebrating knowledge, arts, and new beginnings', 'All districts', 'festival', 'Ancient celebration of Goddess Saraswati and arrival of spring', 'Worship of knowledge, arts, and cultural learning', 'Basant Panchami day (January-February)', 'All community members, especially students and artists', '["yellow_clothes", "flowers", "books", "musical_instruments", "sweets"]', '["morning_prayers", "cultural_programs", "kite_flying", "community_feast", "artistic_competitions"]', '["education", "creativity", "seasonal_harmony", "community_celebration"]', 'Celebrated in schools, colleges, and cultural centers', 'active', '["basant1.jpg", "basant2.jpg"]'),
('Traditional Kumaoni Cuisine Preparation', 'Authentic cooking methods and recipes passed through generations', 'Kumaon region', 'cuisine', 'Developed from local ingredients and seasonal availability', 'Preserves nutritional wisdom and cultural identity through food', 'Daily cooking, festivals, special occasions', 'Women of all ages, increasingly men too', '["traditional_utensils", "local_spices", "seasonal_vegetables", "grains"]', '["ingredient_selection", "traditional_cooking_methods", "seasoning_techniques", "presentation_styles"]', '["health_consciousness", "sustainability", "family_bonding", "cultural_continuity"]', 'Growing interest in organic and traditional cooking', 'active', '["cuisine1.jpg", "cuisine2.jpg"]');
