INSERT INTO chat_messages (chat_id, user_id, message, response, language, ai_model, tokens_used, response_time, confidence_score, context_data, feedback_rating, is_helpful, attachments) VALUES
(1, 1, 'I want to visit Kedarnath temple. What is the best time to go?', 'The best time to visit Kedarnath is from May to October when the temple is open. The weather is pleasant and the trek route is accessible. Avoid monsoon season (July-August) due to heavy rainfall and landslide risks.', 'en', 'llama3.1:8b', 156, 2.3, 0.92, '{"weather_data": "checked", "temple_status": "open_season", "trek_difficulty": "moderate"}', 5, true, null),
(2, 2, 'Can you suggest some beginner yoga poses?', 'Here are some great beginner yoga poses: Mountain Pose (Tadasana), Child''s Pose (Balasana), Downward Dog, and Cat-Cow stretch. Start with these basic poses and hold each for 30 seconds to 1 minute.', 'en', 'llama3.1:8b', 98, 1.8, 0.88, '{"user_level": "beginner", "pose_difficulty": "basic", "safety_checked": true}', 4, true, null),
(3, 3, 'Tell me about traditional Kumaoni folk dances', 'Kumaoni folk dances include Chholiya (sword dance), Jhora (group dance), and Barada Nati. Chholiya is performed during weddings with swords, representing valor and celebration. These dances preserve cultural heritage and community bonding traditions.', 'en', 'llama3.1:8b', 142, 2.1, 0.90, '{"cultural_context": "kumaon_region", "dance_types": "traditional", "cultural_significance": "high"}', 5, true, null),
(4, 4, 'I need emergency contact numbers for Haridwar', 'Here are important emergency contacts for Haridwar: Police: 01334-265308, Hospital (Shri Guru Ram Rai Institute): 01334-286286, Fire Department: 101, Tourist Helpline: 1364. All these services are available 24x7.', 'en', 'llama3.1:8b', 87, 0.9, 0.95, '{"location": "haridwar", "emergency_type": "general", "contacts_verified": true}', 4, true, null),
(5, 5, 'What are the most photogenic places in Uttarakhand?', 'Some of the most photogenic places in Uttarakhand include: Valley of Flowers (alpine flowers), Nainital Lake (reflections), Auli (snow-capped peaks), Rishikesh (Ganga Aarti), Mussoorie (colonial architecture), and Jim Corbett (wildlife photography). Each offers unique photographic opportunities.', 'en', 'llama3.1:8b', 178, 2.5, 0.89, '{"photography_focus": "landscape", "season_considered": "winter", "accessibility": "checked"}', 5, true, null),
(3, 3, 'How can I learn Chholiya dance?', 'You can learn Chholiya dance through cultural workshops in Almora. Master Mohan Singh Rawat offers classes, and there''s an upcoming workshop on March 15-17, 2024. Contact +91-9876543210 for registration. The workshop covers basic steps, sword techniques, and cultural significance.', 'en', 'llama3.1:8b', 134, 1.9, 0.91, '{"workshop_available": true, "instructor_verified": true, "dates_current": true}', 5, true, null),
(1, 1, 'What should I pack for Kedarnath trek?', 'Essential items for Kedarnath trek: warm clothing (layers), waterproof jacket, trekking shoes, first aid kit, torch, power bank, water bottles, energy snacks, sunglasses, sunscreen, and rain cover. Pack light but ensure you have warm clothes for cold nights.', 'en', 'llama3.1:8b', 145, 2.1, 0.93, '{"trek_season": "may", "weather_conditions": "variable", "altitude_considered": true}', 5, true, null),
(2, 2, 'Show me how to do Mountain Pose correctly', 'Mountain Pose (Tadasana): Stand with feet hip-width apart, distribute weight evenly on both feet, engage leg muscles, lengthen spine, relax shoulders away from ears, arms at sides with palms facing forward. Breathe deeply and hold for 1-2 minutes. This pose improves posture and body awareness.', 'en', 'llama3.1:8b', 112, 1.7, 0.94, '{"pose_type": "standing", "difficulty": "beginner", "alignment_cues": "detailed"}', 4, true, null);